"""Sudoku game logic: board generation, validation, and completion checks."""

import random


def find_empty(board):
    for r in range(9):
        for c in range(9):
            if board[r][c] == 0:
                return r, c
    return None


def is_valid(board, r, c, v):
    if any(board[r][x] == v for x in range(9)):
        return False
    if any(board[x][c] == v for x in range(9)):
        return False
    br, bc = 3 * (r // 3), 3 * (c // 3)
    return all(board[i][j] != v
               for i in range(br, br + 3)
               for j in range(bc, bc + 3))


def count_solutions(board, limit=2):
    cell = find_empty(board)
    if cell is None:
        return 1
    r, c = cell
    total = 0
    for v in range(1, 10):
        if is_valid(board, r, c, v):
            board[r][c] = v
            total += count_solutions(board, limit)
            board[r][c] = 0
            if total >= limit:
                break
    return total


def fill_board(board):
    cell = find_empty(board)
    if cell is None:
        return True
    r, c = cell
    digits = list(range(1, 10))
    random.shuffle(digits)
    for v in digits:
        if is_valid(board, r, c, v):
            board[r][c] = v
            if fill_board(board):
                return True
            board[r][c] = 0
    return False


class SudokuGame:
    def __init__(self, holes=45):
        self.solution = [[0] * 9 for _ in range(9)]
        fill_board(self.solution)
        self.board = [row[:] for row in self.solution]
        self.fixed = [[False] * 9 for _ in range(9)]
        self._carve(holes)
        for r in range(9):
            for c in range(9):
                self.fixed[r][c] = self.board[r][c] != 0

    def _carve(self, holes):
        cells = [(r, c) for r in range(9) for c in range(9)]
        random.shuffle(cells)
        removed = 0
        for r, c in cells:
            if removed >= holes:
                break
            backup = self.board[r][c]
            self.board[r][c] = 0
            if count_solutions([row[:] for row in self.board]) != 1:
                self.board[r][c] = backup
            else:
                removed += 1

    def place(self, r, c, v):
        if not (1 <= r <= 9 and 1 <= c <= 9):
            return False, "Row and column must be between 1 and 9."
        r, c = r - 1, c - 1
        if self.fixed[r][c]:
            return False, "That cell is a given clue and cannot be changed."
        if v == 0:
            self.board[r][c] = 0
            return True, f"Cell row {r + 1}, col {c + 1} cleared."
        self.board[r][c] = v
        conflicts = self.conflicts_at(r, c)
        if conflicts:
            return True, (f"Placed {v} at row {r + 1}, col {c + 1}, "
                          f"but it conflicts with: {', '.join(conflicts)}.")
        return True, f"Placed {v} at row {r + 1}, col {c + 1}."

    def conflicts_at(self, r, c):
        v = self.board[r][c]
        if v == 0:
            return []
        conflicts = []
        for x in range(9):
            if x != c and self.board[r][x] == v:
                conflicts.append(f"row {r + 1} col {x + 1}")
            if x != r and self.board[x][c] == v:
                conflicts.append(f"row {x + 1} col {c + 1}")
        br, bc = 3 * (r // 3), 3 * (c // 3)
        for i in range(br, br + 3):
            for j in range(bc, bc + 3):
                if (i, j) != (r, c) and self.board[i][j] == v:
                    conflicts.append(f"row {i + 1} col {j + 1}")
        return conflicts

    def mistakes(self):
        result = []
        for r in range(9):
            for c in range(9):
                conflicts = self.conflicts_at(r, c)
                if self.board[r][c] != 0 and conflicts:
                    result.append((r + 1, c + 1, conflicts))
        return result

    def is_complete(self):
        filled = all(self.board[r][c] != 0 for r in range(9) for c in range(9))
        return filled and not self.mistakes()

    def hint(self):
        empties = [(r, c) for r in range(9) for c in range(9)
                   if self.board[r][c] == 0]
        if not empties:
            return None
